audCC:'"[{\"start\":0,\"editorState\":{\"blocks\":[{\"key\":\"1c5db\",\"text\":\"Finally, let\'s review elimination. This method is useful when both equations are written in the same form. If necessary, multiply one or both equations so that the coefficients of one variable are opposites. Then add the equations, solve for the remaining variable, and then substitute back into one of the original equations to find the second variable.\",\"type\":\"unstyled\",\"depth\":0,\"inlineStyleRanges\":[{\"offset\":0,\"length\":354,\"style\":\"textOutlineEnable:false\"},{\"offset\":0,\"length\":354,\"style\":\"opacity:1\"},{\"offset\":0,\"length\":354,\"style\":\"defaultTextStrokeColor:#F1EEE6\"},{\"offset\":0,\"length\":354,\"style\":\"hlnke:true\"},{\"offset\":0,\"length\":354,\"style\":\"defaultTextShadow:none\"},{\"offset\":0,\"length\":354,\"style\":\"tablet-fontSize:24\"},{\"offset\":0,\"length\":354,\"style\":\"textShadow:none\"},{\"offset\":0,\"length\":354,\"style\":\"textShadowX:0px\"},{\"offset\":0,\"length\":354,\"style\":\"fontStretch:normal\"},{\"offset\":0,\"length\":354,\"style\":\"fontType:regular\"},{\"offset\":0,\"length\":354,\"style\":\"color:#ffffff\"},{\"offset\":0,\"length\":354,\"style\":\"defaultBackgroundColor:#E8D01B\"},{\"offset\":0,\"length\":354,\"style\":\"textShadowY:4px\"},{\"offset\":0,\"length\":354,\"style\":\"textShadowColor:#F1EEE61F\"},{\"offset\":0,\"length\":354,\"style\":\"lineHeight:135%\"},{\"offset\":0,\"length\":354,\"style\":\"letterSpacing:0%\"},{\"offset\":0,\"length\":354,\"style\":\"textHighlightEnable:false\"},{\"offset\":0,\"length\":354,\"style\":\"textTransform:none\"},{\"offset\":0,\"length\":354,\"style\":\"textShadowOpacity:none\"},{\"offset\":0,\"length\":354,\"style\":\"overridden:true\"},{\"offset\":0,\"length\":354,\"style\":\"textDecoration:none\"},{\"offset\":0,\"length\":354,\"style\":\"fontFamily:Georgia\"},{\"offset\":0,\"length\":354,\"style\":\"borderBottomStyle:none\"},{\"offset\":0,\"length\":354,\"style\":\"textShadowEnable:false\"},{\"offset\":0,\"length\":354,\"style\":\"hlnk:\"},{\"offset\":0,\"length\":354,\"style\":\"fontWeight:normal\"},{\"offset\":0,\"length\":354,\"style\":\"textShadowBlur:8px\"},{\"offset\":0,\"length\":354,\"style\":\"desktop-fontSize:24\"},{\"offset\":0,\"length\":354,\"style\":\"backgroundColor:unset\"},{\"offset\":0,\"length\":354,\"style\":\"WebkitTextStrokeWidth:1px\"},{\"offset\":0,\"length\":354,\"style\":\"hlnkt:wp\"},{\"offset\":0,\"length\":354,\"style\":\"fontStyle:normal\"},{\"offset\":0,\"length\":354,\"style\":\"mobile-fontSize:24\"},{\"offset\":0,\"length\":354,\"style\":\"defaultTextStrokeWidth:1px\"},{\"offset\":0,\"length\":354,\"style\":\"WebkitTextStrokeColor:#F1EEE6\"}],\"entityRanges\":[],\"data\":{\"listDepth\":\"0\",\"listColor\":\"#666666\",\"listIndent\":\"100%\",\"verticalAlign\":\"middle\",\"overridden\":\"true\",\"marginLeft\":\"0px\",\"listType\":\"S_Bullets08\",\"textAlign\":\"center\",\"marginBottom\":\"0%\",\"presetId\":\"text-closedcaptions\",\"listSize\":\"100%\"}}],\"entityMap\":{}},\"CCPosition\":\"BOTTOM\",\"text\":\"Finally, let\'s review elimination. This method is useful when both equations are written in the same form. If necessary, multiply one or both equations so that the coefficients of one variable are opposites. Then add the equations, solve for the remaining variable, and then substitute back into one of the original equations to find the second variable.\",\"duration\":24.2,\"end\":24.2,\"id\":\"caption__3574__6\",\"dirtyReasons\":[],\"speechAgentV1\":{\"name\":\"Nichalia Schwartz\",\"voiceId\":{\"uid\":\"XfNU2rGpBa01ckF309OY\",\"modelId\":\"1\"},\"source\":\"AIVoices\"}}]"',
